from pathlib import Path
import re,zlib,base64,json
root=Path('.')
index=root/'index.html'
html=index.read_text(encoding='utf-8')
replacement=zlib.decompress(base64.b64decode('')).decode('utf-8')
pattern=re.compile(r'async function saveSettlementPng\(autoShare\)\{.*?\n\}\n\n(?=function companyProfile)',re.S)
html,n=pattern.subn(replacement,html)
if n!=1: raise SystemExit(f'PNG renderer replace count={n}')
html=html.replace('v5.6.1','v5.6.2').replace('"5.6.1"','"5.6.2"')
index.write_text(html,encoding='utf-8')
(root/'version.json').write_text(json.dumps({"version":"5.6.2","message":"월간 정산서 PNG를 더 선명하고 세련된 카드형 디자인으로 리뉴얼하고 가독성을 개선했습니다."},ensure_ascii=False,indent=2),encoding='utf-8')
sw=(root/'service-worker.js').read_text(encoding='utf-8').replace('rabic-gongsu-pro-v5-6-1','rabic-gongsu-pro-v5-6-2')
(root/'service-worker.js').write_text(sw,encoding='utf-8')
print('patched v5.6.2')
